using Oathx.Core;
using Oathx.Entity;

/// <summary>
/// Local login success notification that permits game startup.
/// </summary>
public class LoginSucceed : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int pid 
    { get; set; }
}

/// <summary>
/// Local login failure notification.
/// </summary>
public class LoginFailure : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int code
    { get; set; }
}

/// <summary>
/// Coordinates local player persistence and business system startup.
/// </summary>
public class MasterSystem : RuntimeSystem
{
    /// <summary>
    /// Subscribe to local login success without starting Home.
    /// </summary>
    /// <returns>True after registering the local login handler.</returns>
    public override bool OnActive()
    {
        Subscribe<LoginSucceed>(OnLoginSucceed);

        return true;
    }

    /// <summary>
    /// Prepare local player data and start Home after local login succeeds.
    /// </summary>
    /// <param name="data">Local login success notification.</param>
    private void OnLoginSucceed(LoginSucceed data)
    {
        if (Load())
        {
            Launch();
        }
    }

    /// <summary>
    /// Release local event subscriptions and unload Home.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        Unload();
    }

    /// <summary>
    /// Restore local data or persist initial values before starting business systems.
    /// </summary>
    /// <returns>True when local player data is ready.</returns>
    public bool Load()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        bool ready = master.ExistsSerializeFile()
            ? master.Deserialize()
            : !string.IsNullOrEmpty(master.Serialize());
        if (!ready)
            return false;

        return true;
    }

    /// <summary>
    /// Unload Home, including during deactivation.
    /// </summary>
    /// <returns>True after requesting Home removal from the dispatcher.</returns>
    public bool Unload()
    {
        dispatcher.Unload(typeof(HomeSystem));

        return true;
    }

    /// <summary>
    /// Persist the current local player data without contacting a server.
    /// </summary>
    /// <returns>True when the local archive has been written.</returns>
    public bool Save()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        return !string.IsNullOrEmpty(master.Serialize());
    }

    /// <summary>
    /// Unload login and request Home startup.
    /// </summary>
    /// <returns>True when the transition has been requested.</returns>
    private bool Launch()
    {
        if (!IsActive())
            return false;

        UnloadSystem(typeof(LoginSystem), () => {
            if (IsActive())
            {
                LoadSystem(typeof(HomeSystem));
            }
        });

        return true;
    }
}

using Config;
using Newtonsoft.Json;
using Oathx.Entity;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// master property define
/// </summary>
public class MasterPropertyDef
{
    public const int PID = 0;
    public const int LV = 1;
    public const int VIP = 2;
    public const int MONEY = 3;
    public const int DIAMOND = 4;
    public const int CHAPTER = 5;
    public const int LEVEL = 6;
}

/// <summary>
/// master entity
/// </summary>
[Initialize]
public class MasterEntity : XEntitySerialize
{
    /// <summary>
    /// constructor
    /// </summary>
    public MasterEntity()
    {
        InitAttrs();
    }

    /// <summary>
    /// init master attrs
    /// </summary>
    private void InitAttrs()
    {
        var sampleAttrs = new Dictionary<int, int>() {
            { MasterPropertyDef.PID, 0 },
            { MasterPropertyDef.LV, 1 },
            { MasterPropertyDef.VIP, 1 },
            { MasterPropertyDef.MONEY, 3000 },
            { MasterPropertyDef.DIAMOND, 100 },
            { MasterPropertyDef.CHAPTER, Excel.CHAPTER_HOME},
            { MasterPropertyDef.LEVEL, 0 }
        };

        ApplyAttrs(sampleAttrs);
    }

    /// <summary>
    /// try get chapter and level
    /// </summary>
    /// <param name="levelId"></param>
    /// <returns></returns>
    public int TryGetChapter(out int levelId)
    {
        levelId = GetAttr(MasterPropertyDef.LEVEL);
        return GetAttr(MasterPropertyDef.CHAPTER);
    }
}

using System.Collections;
using UnityEngine;
using Oathx.Core;

/// <summary>
/// runtime logic system
/// </summary>
public abstract class RuntimeSystem : XEventModule
{
    /// <summary>
    /// load system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public virtual void LoadSystem(System.Type type, System.Action complete=null)
    {
        XCoroutine.Run(DoLoadAsync(type, complete));
    }

    /// <summary>
    /// do load async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    private IEnumerator DoLoadAsync(System.Type type, System.Action complete)
    {
        dispatcher.Load(type);
        yield return new WaitForEndOfFrame();

        complete?.Invoke();
    }

    /// <summary>
    /// unload system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public void UnloadSystem(System.Type type, System.Action complete)
    {
        XCoroutine.Run(DoUnloadAsync(type, complete));
    }

    /// <summary>
    /// do unload async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    IEnumerator DoUnloadAsync(System.Type type, System.Action complete)
    {
        dispatcher.Unload(type);
        yield return new WaitForEndOfFrame();
        complete?.Invoke();
    }
}
